-- NileStock V1: multi-tenant schema, security, and atomic checkout
create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','manager','cashier');
create type public.sale_status as enum ('completed','refunded','voided');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text,email text,created_at timestamptz default now());
create table public.businesses(id uuid primary key default gen_random_uuid(),name text not null,country text not null default 'Uganda',currency char(3) not null default 'UGX',timezone text not null default 'Africa/Kampala',phone text,email text,address text,tax_rate numeric(7,4) not null default 0,low_stock_threshold bigint not null default 2,receipt_footer text default 'Thank you for shopping with us.',settings jsonb not null default '{}',plan text not null default 'free' check(plan in('free','starter','business','pro')),created_at timestamptz default now());
create table public.business_members(business_id uuid references public.businesses on delete cascade,user_id uuid references auth.users on delete cascade,role public.member_role not null,status text not null default 'active' check(status in('active','disabled')),created_at timestamptz default now(),primary key(business_id,user_id));
create table public.categories(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,name text not null,created_at timestamptz default now(),unique(business_id,name));
create table public.suppliers(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,name text not null,phone text,email text,address text,contact_person text,notes text,balance bigint not null default 0,created_at timestamptz default now());
create table public.customers(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,name text not null,phone text,email text,address text,notes text,balance bigint not null default 0,created_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,category_id uuid references public.categories on delete set null,supplier_id uuid references public.suppliers on delete set null,name text not null,description text,sku text not null,barcode text,qr_value text,selling_price bigint not null check(selling_price>=0),cost_price bigint not null default 0 check(cost_price>=0),stock bigint not null default 0,reorder_level bigint not null default 2,unit text not null default 'piece',taxable boolean default false,active boolean default true,image_path text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(business_id,sku),unique(business_id,barcode),unique(business_id,qr_value));
create table public.product_variants(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,product_id uuid not null references public.products on delete cascade,name text not null,sku text not null,barcode text,selling_price bigint not null,cost_price bigint not null default 0,stock bigint not null default 0,unique(business_id,sku),unique(business_id,barcode));
create table public.sales(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,receipt_no text not null,customer_id uuid references public.customers on delete set null,cashier_id uuid references auth.users on delete set null,status public.sale_status not null default 'completed',subtotal bigint not null,discount bigint not null default 0,tax bigint not null default 0,total bigint not null,payment_method text not null,amount_paid bigint not null,change_due bigint not null default 0,note text,offline_id text,created_at timestamptz default now(),unique(business_id,receipt_no),unique(business_id,offline_id));
create table public.sale_items(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,sale_id uuid not null references public.sales on delete cascade,product_id uuid not null references public.products,product_name text not null,quantity bigint not null check(quantity>0),unit_price bigint not null,cost_price bigint not null,item_discount bigint not null default 0);
create table public.payments(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,sale_id uuid references public.sales on delete cascade,customer_id uuid references public.customers on delete set null,kind text not null default 'sale',method text not null,amount bigint not null,created_at timestamptz default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,product_id uuid not null references public.products,quantity bigint not null,movement_type text not null,reference text,actor_id uuid references auth.users on delete set null,notes text,created_at timestamptz default now());
create table public.purchases(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,supplier_id uuid references public.suppliers on delete set null,reference text not null,purchase_date date not null,total bigint not null,amount_paid bigint not null default 0,notes text,created_by uuid references auth.users,created_at timestamptz default now());
create table public.purchase_items(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,purchase_id uuid not null references public.purchases on delete cascade,product_id uuid not null references public.products,quantity bigint not null check(quantity>0),unit_cost bigint not null check(unit_cost>=0));
create table public.expenses(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,category text not null,description text not null,amount bigint not null check(amount>0),payment_method text not null,expense_date date not null,payee text,reference text,notes text,created_by uuid references auth.users,created_at timestamptz default now());
create table public.credit_transactions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,customer_id uuid not null references public.customers on delete cascade,sale_id uuid references public.sales,kind text not null check(kind in('credit_sale','repayment','adjustment')),amount bigint not null,created_at timestamptz default now());
create table public.held_sales(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,name text not null,cart jsonb not null,created_by uuid references auth.users,created_at timestamptz default now());
create table public.stocktakes(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,status text not null default 'open',created_by uuid references auth.users,approved_by uuid references auth.users,created_at timestamptz default now(),completed_at timestamptz);
create table public.stocktake_items(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,stocktake_id uuid references public.stocktakes on delete cascade,product_id uuid references public.products,expected bigint not null,actual bigint,unique(stocktake_id,product_id));
create table public.shifts(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,cashier_id uuid references auth.users,opening_cash bigint not null,expected_cash bigint, counted_cash bigint,opened_at timestamptz default now(),closed_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,user_id uuid references auth.users,title text not null,body text,read_at timestamptz,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,business_id uuid not null references public.businesses on delete cascade,actor_id uuid references auth.users,action text not null,entity_type text,entity_id text,metadata jsonb default '{}',created_at timestamptz default now());
create table public.customer_requests(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,product_name text not null,customer_id uuid references public.customers on delete set null,customer_name text,phone text,quantity bigint not null default 1,notes text,status text not null default 'open' check(status in('open','sourced','closed')),created_by uuid references auth.users,created_at timestamptz default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,plan text not null check(plan in('free','starter','business','pro')),billing_cycle text not null default 'monthly' check(billing_cycle in('monthly','annual')),status text not null default 'pending' check(status in('pending','active','past_due','cancelled')),amount bigint not null default 0,current_period_start timestamptz,current_period_end timestamptz,provider text,provider_reference text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.billing_requests(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,requested_plan text not null check(requested_plan in('free','starter','business','pro')),billing_cycle text not null check(billing_cycle in('monthly','annual')),payment_method text not null,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),requested_by uuid references auth.users,created_at timestamptz default now());
create index products_search_idx on public.products(business_id,active,name);create index products_code_idx on public.products(business_id,barcode);create index sales_date_idx on public.sales(business_id,created_at desc);create index movement_product_idx on public.inventory_movements(business_id,product_id,created_at desc);create index expenses_date_idx on public.expenses(business_id,expense_date desc);create index audit_idx on public.audit_logs(business_id,created_at desc);
create or replace function public.is_member(bid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from business_members where business_id=bid and user_id=auth.uid() and status='active')$$;
create or replace function public.has_role(bid uuid,roles member_role[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from business_members where business_id=bid and user_id=auth.uid() and role=any(roles) and status='active')$$;
alter table profiles enable row level security;create policy profile_self on profiles for all using(id=auth.uid()) with check(id=auth.uid());
alter table businesses enable row level security;create policy business_select on businesses for select using(public.is_member(id));create policy business_update on businesses for update using(public.has_role(id,array['owner'::member_role])) with check(public.has_role(id,array['owner'::member_role]));
do $$declare t text;begin foreach t in array array['business_members','categories','suppliers','customers','products','product_variants','sales','sale_items','payments','inventory_movements','purchases','purchase_items','expenses','credit_transactions','held_sales','stocktakes','stocktake_items','shifts','notifications','audit_logs','customer_requests','subscriptions','billing_requests'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy tenant_select on public.%I for select using(public.is_member(business_id))',t);execute format('create policy tenant_insert on public.%I for insert with check(public.is_member(business_id))',t);execute format('create policy tenant_update on public.%I for update using(public.has_role(business_id,array[''owner''::member_role,''manager''::member_role])) with check(public.has_role(business_id,array[''owner''::member_role,''manager''::member_role]))',t);execute format('create policy tenant_delete on public.%I for delete using(public.has_role(business_id,array[''owner''::member_role]))',t);end loop;end$$;
-- Business creation is handled by this function because membership does not exist yet.
create or replace function public.create_business(p_name text,p_phone text default null) returns uuid language plpgsql security definer set search_path=public as $$declare bid uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;insert into businesses(name,phone)values(p_name,p_phone)returning id into bid;insert into business_members values(bid,auth.uid(),'owner','active',now());insert into profiles(id,email)values(auth.uid(),auth.jwt()->>'email')on conflict(id)do nothing;return bid;end$$;grant execute on function public.create_business(text,text) to authenticated;
create or replace function public.notify_low_stock() returns trigger language plpgsql security definer set search_path=public as $$begin if new.stock<=new.reorder_level and (old.stock>old.reorder_level or old.stock is null) then insert into notifications(business_id,title,body)values(new.business_id,'Low stock: '||new.name,new.stock||' remaining. Alert level: '||new.reorder_level);end if;return new;end$$;
create trigger products_low_stock_alert after update of stock on public.products for each row execute function public.notify_low_stock();
-- Atomic sale: locks products, validates stock, writes finance, stock ledger and debt as one transaction.
create or replace function public.complete_sale(p_business uuid,p_receipt text,p_customer uuid,p_payment text,p_paid bigint,p_discount bigint,p_tax bigint,p_items jsonb,p_offline_id text default null) returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid;subtotal bigint:=0;totalv bigint;it jsonb;prod products%rowtype;begin if not has_role(p_business,array['owner'::member_role,'manager'::member_role,'cashier'::member_role]) then raise exception 'Permission denied';end if;for it in select * from jsonb_array_elements(p_items) loop select * into prod from products where id=(it->>'product_id')::uuid and business_id=p_business for update;if not found or prod.stock<(it->>'quantity')::bigint then raise exception 'Insufficient stock for product';end if;subtotal:=subtotal+(it->>'quantity')::bigint*prod.selling_price;end loop;totalv:=subtotal-p_discount+p_tax;if totalv<0 then raise exception 'Invalid total';end if;insert into sales(business_id,receipt_no,customer_id,cashier_id,subtotal,discount,tax,total,payment_method,amount_paid,change_due,offline_id)values(p_business,p_receipt,p_customer,auth.uid(),subtotal,p_discount,p_tax,totalv,p_payment,p_paid,greatest(0,p_paid-totalv),p_offline_id)returning id into sid;for it in select * from jsonb_array_elements(p_items) loop select * into prod from products where id=(it->>'product_id')::uuid;insert into sale_items(business_id,sale_id,product_id,product_name,quantity,unit_price,cost_price,item_discount)values(p_business,sid,prod.id,prod.name,(it->>'quantity')::bigint,prod.selling_price,prod.cost_price,coalesce((it->>'discount')::bigint,0));update products set stock=stock-(it->>'quantity')::bigint,updated_at=now() where id=prod.id;insert into inventory_movements(business_id,product_id,quantity,movement_type,reference,actor_id)values(p_business,prod.id,-(it->>'quantity')::bigint,'Sale',p_receipt,auth.uid());end loop;insert into payments(business_id,sale_id,customer_id,method,amount)values(p_business,sid,p_customer,p_payment,totalv);if p_payment='Customer Credit' then if p_customer is null then raise exception 'Customer required for credit';end if;update customers set balance=balance+totalv where id=p_customer and business_id=p_business;insert into credit_transactions(business_id,customer_id,sale_id,kind,amount)values(p_business,p_customer,sid,'credit_sale',totalv);end if;insert into audit_logs(business_id,actor_id,action,entity_type,entity_id)values(p_business,auth.uid(),'sale.completed','sale',sid::text);return sid;end$$;grant execute on function public.complete_sale(uuid,text,uuid,text,bigint,bigint,bigint,jsonb,text) to authenticated;
